        self.expression = expression
        self.pos = 0
        self.current_char = self.expression[self.pos] if self.expression else None

    def error(self):
        raise Exception("Invalid expression")

    def advance(self):
        self.pos += 1
        if self.pos < len(self.expression):
            self.current_char = self.expression[self.pos]
        else:
            self.current_char = None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self):
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return float(result)

    def factor(self):
        if self.current_char == '(':
            self.advance()
            result = self.expr()
            if self.current_char == ')':
                self.advance()
                return result
            else:
                self.error()
        else:
            return self.number()

    def term(self):
        result = self.factor()
        while self.current_char is not None and self.current_char in ('*', '/'):
            op = self.current_char
            self.advance()
            if op == '*':
                result *= self.factor()
            elif op == '/':
                result /= self.factor()
        return result

    def expr(self):
        result = self.term()
        while self.current_char is not None and self.current_char in ('+', '-'):
            op = self.current_char
            self.advance()
            if op == '+':
                result += self.term()
            elif op == '-':
                result -= self.term()
        return result

